"""Green/gold GSAP edition. Shared templates installed by build.py."""
import html

b = None
INTRO = 'For over two decades, cultivating a vibrant sanctuary for spiritual enrichment, profound theological learning, and open intellectual discourse across the LUMS community.'
PHILOSOPHY = 'At LRS, we believe spiritual conviction is strengthened through sincere inquiry, honest dialogue, and intellectual engagement. We provide an open forum for LUMS students to engage with renowned scholars, explore Islamic philosophy, tackle contemporary moral questions, and bridge the gap between academic disciplines and sacred wisdom.'
PILLARS = [
 ('Spiritual Growth','Weekly halaqas, intensive Surah workshops, and heart-softening reminders centered on Quranic contemplation, Tazkiyah, and deep love for the Prophet (SAW).','lums-mosque.jpg'),
 ('Intellectual Rigor','Open, fearless exploration of theology, Islamic philosophy, epistemology, and contemporary socio-ethical dilemmas with renowned academics and scholars.','community-11.jpg'),
 ('Social Solidarity','Translating faith into proactive compassion through nationwide charity drives, active Palestinian solidarity, campus welfare, and youth mentoring.','community-9.jpg')]

def media(name): return b.asset('media/'+name)
def img(name,alt,cls='',lazy=True): return f'<img src="{media(name)}" alt="{b.esc(alt)}" class="{cls}" {"loading=lazy" if lazy else "fetchpriority=high"} decoding="async">'
def link(*args,**kwargs): return b.link(*args,**kwargs)
def line(): return '<svg class="gold-rule" viewBox="0 0 1200 24" preserveAspectRatio="none" aria-hidden="true"><path d="M0 12H580L600 1L620 12H1200M580 12L600 23L620 12" fill="none" stroke="currentColor"/></svg>'
def brand(): return f'<img class="brand-symbol original-logo" src="{media("lrs-logo.png")}" alt=""><span class="brand-name">LUMS Religious<br>Society<small>Faith · Awareness · Integrity</small></span>'

def layout(route,title,description,body):
    nav=[('about','Our Society','community-9.jpg'),('events','Gatherings','community-2.jpg'),('mosque','The Masjid','lums-mosque.jpg'),('lrf','LRF','community-5.jpg'),('tafakkur','Tafakkur','community-11.jpg'),('learn','Learn & Reflect','community-1.jpg'),('palestine','Palestine','community-7.jpg')]
    nav_links=''.join(f'<a href="{b.url(r)}" data-nav-image="{media(photo)}"><span class="nav-index">0{i}</span><span class="nav-word">{name}</span><span class="nav-arrow" aria-hidden="true">↗</span></a>' for i,(r,name,photo) in enumerate(nav,1))
    scripts=''.join(f'<script src="{b.asset("vendor/"+name+".min.js")}" defer></script>' for name in ['gsap','ScrollTrigger','SplitText','Flip','DrawSVGPlugin','Observer'])
    scripts+=f'<script src="{b.asset("vendor/suncalc.js")}" defer></script>'
    scripts+=''.join(f'<script src="{b.asset("js/"+name+".js")}" defer></script>' for name in ['data','prayer-engine','app','motion'])
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#073e2d"><title>{b.esc(title)} | LUMS Religious Society</title><meta name="description" content="{b.esc(description)}"><link rel="icon" href="{media('lrs-logo.png')}"><link rel="stylesheet" href="{b.asset('css/fonts.css')}"><link rel="stylesheet" href="{b.asset('css/styles.css')}"><link rel="stylesheet" href="{b.asset('css/cinematic.css')}">{scripts}</head>
<body class="cinematic" data-route="{b.esc(route)}" data-base="{b.BASE}"><a href="#main" class="skip">Skip to content</a><div class="page-progress" aria-hidden="true"></div>
<header class="cinema-header"><a class="brand" href="{b.url()}" aria-label="LRS home">{brand()}</a><span class="header-motto">Faith. Awareness. Integrity.</span><div class="header-actions"><a class="quick-prayer" href="{b.url('mosque/timings')}">Prayer timings <span aria-hidden="true">↗</span></a><button type="button" class="menu-trigger" aria-controls="cinema-menu" aria-expanded="false"><span>Menu</span><span class="menu-glyph" aria-hidden="true"><i></i><i></i></span></button></div></header>
<dialog id="cinema-menu" class="cinema-menu" aria-label="Explore LRS"><div class="menu-top"><a href="{b.url()}" class="brand">{brand()}</a><span class="eyebrow">Explore the society</span><button class="menu-close" type="button">Close <span aria-hidden="true">×</span></button></div><div class="menu-layout"><nav class="cinema-nav" aria-label="Main navigation">{nav_links}</nav><div class="menu-picture"><div class="menu-picture-inner">{img('lums-mosque.jpg','LUMS mosque','nav-preview',False)}<div class="menu-picture-shade"></div><p>Rooted in faith.<br><em>Open to discovery.</em></p></div><svg class="menu-arch" viewBox="0 0 400 530" aria-hidden="true"><path d="M10 520V210C10 90 90 15 200 10C310 15 390 90 390 210V520Z" fill="none" stroke="currentColor"/></svg></div></div><div class="menu-bottom"><a href="{b.url('mosque/brothers')}">Brothers’ activities</a><a href="{b.url('mosque/sisters')}">Sisters’ activities</a><a href="{b.url('publications')}">Publications</a><a href="{b.url('get-involved')}">Get involved</a><a href="{b.url('contact')}">Contact LRS ↗</a></div></dialog>
<main id="main">{body}</main>
<footer class="footer cinematic-footer"><div class="wrap"><div class="footer-invitation"><p class="eyebrow">Faith • Awareness • Integrity</p><a href="{b.url('get-involved')}">Be part of<br><em>something meaningful.</em><span aria-hidden="true">↗</span></a></div>{line()}<div class="footer-top"><div class="footer-brand"><a href="{b.url()}" class="brand">{brand()}</a><p>The LUMS Religious Society (LRS) fosters spiritual enrichment, profound learning, and open intellectual discourse across the university community.</p></div><div><h3>The society</h3><div class="footer-links"><a href="{b.url('about')}">Our mission</a><a href="{b.url('lrf')}">LRF editions</a><a href="{b.url('tafakkur')}">Tafakkur</a><a href="{b.url('palestine')}">Palestinian Cause</a></div></div><div><h3>Community</h3><div class="footer-links"><a href="{b.url('events')}">Events & archives</a><a href="{b.url('mosque/sisters')}">Sisters’ activities</a><a href="{b.url('mosque/brothers')}">Brothers’ activities</a><a href="{b.url('gallery')}">Moments & memories</a></div></div><div><h3>Contact LRS</h3><div class="footer-links"><a href="mailto:faith@lums.edu.pk">faith@lums.edu.pk</a><a href="tel:+923250318229">+92 325 0318229</a><a href="{b.url('contact')}">Contact & FAQs</a><a href="{b.url('privacy')}">Privacy</a></div></div></div><div class="footer-bottom"><span>© <span data-year>2026</span> LUMS Religious Society</span><span>LUMS DHA, Lahore Cantt, 54792, Lahore, Pakistan</span></div></div></footer>
<div class="toast" role="status" aria-live="polite" hidden></div><dialog class="dialog" aria-label="Community photograph"><img src="{media('community-9.jpg')}" alt="Selected community photograph"><div class="dialog-controls"><p class="dialog-caption"></p><button type="button" data-close-dialog>Close ×</button></div></dialog></body></html>'''

def art(e,cls=''):
    photos={'sacred-retreat-2':'lums-mosque.jpg','why-al-aqsa-still-calls-us':'community-7.jpg','friday-morning-with-chai':'community-3.jpg','ultimate-trust-fall':'community-11.jpg'}
    return f'<div class="card-art photographic {cls}">{img(photos.get(e["slug"],"community-2.jpg"),"LRS archive photograph; contextual image, not a photograph of this event")}<span class="photo-credit">LRS archive · contextual image</span></div>'

def event_showcase():
    slides=[]
    for i,e in enumerate(b.DATA['events']):
        photo={'sacred-retreat-2':'lums-mosque.jpg','why-al-aqsa-still-calls-us':'community-7.jpg','friday-morning-with-chai':'community-3.jpg','ultimate-trust-fall':'community-11.jpg'}[e['slug']]
        slides.append(f'''<article class="event-slide {'is-active' if i==0 else ''}" data-featured-event="{e['slug']}" aria-label="{i+1} of {len(b.DATA['events'])}" {'inert aria-hidden=true' if i else ''}>{img(photo,'LRS archive photograph used as an event background','slide-photo',i>0)}<div class="slide-shade"></div><div class="slide-layout"><div class="slide-label"><span class="eyebrow">LRS gatherings</span><span class="slide-status" data-slide-status>Event announcement</span></div><div class="slide-copy"><p class="eyebrow slide-kicker">{b.esc(e['subtitle'])}</p><h2 class="slide-title">{b.esc(e['title'])}</h2><p class="slide-description">{b.esc(e['description'])}</p><div class="slide-details"><span>{b.date_label(e)}<br>{b.esc(e['time'])}</span><span>{b.esc(e['venue'])}<br>{b.audience(e)}</span></div>{link('events/'+e['slug'],'Explore this gathering','btn light')}</div><span class="slide-side">LRS archive photography · contextual background</span></div></article>''')
    return f'''<section class="event-cinema" id="gatherings" aria-label="Featured LRS events" aria-roledescription="carousel"><div class="event-stage">{''.join(slides)}<div class="event-controls"><div class="event-count"><span data-slide-number>01</span><span class="counter-line"></span><span>{len(b.DATA["events"]):02d}</span></div><div class="event-progress" aria-hidden="true"><span></span></div><div class="slide-buttons"><button type="button" data-slide-prev aria-label="Previous event">←</button><button type="button" data-slide-pause aria-pressed="false">Pause</button><button type="button" data-slide-next aria-label="Next event">→</button></div><a href="{b.url('events')}">All events ↗</a></div></div><p class="sr-only" data-slide-announcement aria-live="polite"></p></section>'''

def prayer_scene():
    prayers=''.join(f'<button class="solar-prayer" data-solar-prayer="{key}" aria-pressed="false"><span class="prayer-number">0{i}</span><span>{name}</span><time data-solar-time="{key}">—</time><span class="prayer-caption">Jama‘at</span></button>' for i,(key,name) in enumerate([('fajr','Fajr'),('zuhr','Zuhr'),('asr','Asr'),('maghrib','Maghrib'),('isha','Isha')],1))
    return f'''<section class="solar-section" id="prayer-experience" aria-label="LUMS mosque prayer times and live sky"><div class="solar-frame"><div class="solar-world" aria-hidden="true"><div class="solar-sky"></div><div class="solar-stars"></div><div class="solar-haze"></div><div class="solar-sun"></div><div class="solar-moon"></div>{img('lums-mosque.jpg','LUMS mosque exterior','solar-mosque',False)}<div class="solar-photo-tint"></div><div class="solar-night-glow"></div><div class="solar-vignette"></div></div><div class="solar-content wrap"><div class="solar-heading"><div><p class="eyebrow">LUMS Masjid · a rhythm of remembrance</p><h2>Pause.<br><em>Turn towards Him.</em></h2></div><div class="solar-clock"><span class="eyebrow">Lahore · Pakistan</span><time data-live-clock>Current time</time><p data-solar-phase>Following the light</p></div></div><div class="solar-footer"><div class="solar-status"><p data-solar-status aria-live="polite">A day unfolds, then settles at the current Lahore time.</p><div><button class="solar-replay" type="button">Replay day ↻</button><button class="solar-live" type="button" hidden>Return to live time ↗</button></div></div><div class="solar-prayers">{prayers}</div><div class="solar-links"><p data-schedule-note>Published mosque timetable · calculated sunrise and sunset</p>{link('mosque/timings','Full schedule & guidelines')}</div></div></div><div class="solar-exit-veil" aria-hidden="true"></div><span class="solar-scroll">Continue scrolling <span aria-hidden="true">↓</span></span></div></section>'''

def pillars():
    panels=''.join(f'<article class="pillar-story"><div class="pillar-photo">{img(photo,title)}</div><div class="pillar-story-copy"><p class="eyebrow">The three pillars of LRS · 0{i}</p><h3>{title}</h3><p>{text}</p><svg class="pillar-symbol" viewBox="0 0 120 120" aria-hidden="true"><path d="M60 5 76 38 112 26 94 60 112 94 76 82 60 115 44 82 8 94 26 60 8 26 44 38Z" fill="none" stroke="currentColor"/></svg></div></article>' for i,(title,text,photo) in enumerate(PILLARS,1))
    return f'<div class="pillar-stories">{panels}</div>'

def programme_card():
    p=b.DATA['programmes'][0]
    return f'<article class="programme-card"><div class="programme-ornament" aria-hidden="true">۞</div><div><p class="eyebrow">Sisters · weekly Quran circle</p><h3>{p["title"]}</h3><p>{p["schedule"]}<br>{p["venue"]}</p>{link("programmes/"+p["slug"],"Explore the circle")}</div></article>'

def community():
    return f'''<section class="community-section section" id="circles"><div class="wrap">{b.section_head('Life at the Masjid','Faith, in <em>good company.</em>',link('mosque','Mosque & community'))}<div class="community-switch" role="tablist" aria-label="Community activities"><button role="tab" aria-selected="true" aria-controls="community-brothers" id="tab-brothers" data-community-tab="brothers">Brothers’ activities <span>01</span></button><button role="tab" aria-selected="false" aria-controls="community-sisters" id="tab-sisters" data-community-tab="sisters" tabindex="-1">Sisters’ activities <span>02</span></button><div class="community-indicator"></div></div><div class="community-panels"><div id="community-brothers" role="tabpanel" aria-labelledby="tab-brothers" class="community-panel"><div class="community-image">{img('community-2.jpg','LRS community gathering from the society archive')}</div><div class="community-copy"><p class="eyebrow">Gather. Reflect. Reconnect.</p><h3>A place for<br><em>shared purpose.</em></h3><p>Explore gatherings and retreats relevant to brothers. The Sacred Retreat includes separate arrangements for brothers and sisters.</p>{link('mosque/brothers','Explore brothers’ activities','btn')}<p class="fine">Check each announcement for its venue, date, and registration details.</p></div></div><div id="community-sisters" role="tabpanel" aria-labelledby="tab-sisters" class="community-panel" hidden><div class="community-image">{img('lums-mosque.jpg','LUMS mosque exterior; not a photograph of the female prayer space')}</div><div class="community-copy"><p class="eyebrow">A circle to return to</p><h3>Learning, friendship,<br><em>and reflection.</em></h3><p>Explore the Surah Hadid circle, halaqas, and community gatherings on the female side of the masjid.</p>{link('mosque/sisters','Explore sisters’ activities','btn')}{programme_card()}</div></div></div></div></section>'''

def verse():
    v=b.DATA['verses'][0]
    return f'''<section class="verse-section section" aria-label="Quranic verse of the day"><div class="verse-geometry" aria-hidden="true">✧</div><div class="wrap"><div class="verse-box"><svg class="verse-border" viewBox="0 0 1000 560" preserveAspectRatio="none" aria-hidden="true"><path d="M500 10H990V550H10V10H500" fill="none" stroke="currentColor"/></svg><p class="eyebrow">A moment of reflection · Verse of the day</p><p class="arabic" lang="ar" dir="rtl" data-verse-arabic>{v['arabic']}</p><p class="verse-translation" data-verse-translation>{v['translation']}</p><p class="verse-reference" data-verse-reference>Surah {v['surah']} · {v['reference']}</p><p class="verse-credit" data-verse-credit>{v['translator']}</p><div class="verse-actions"><a data-verse-source href="{v['source']}">Read & listen ↗</a><button type="button" data-copy-verse>Copy verse</button><button type="button" data-share-verse>Share</button></div></div></div></section>'''

def gallery():
    items=[('community-9.jpg','LRS community and speakers'),('community-11.jpg','A moment of intellectual exchange'),('community-3.jpg','Hospitality and community'),('community-2.jpg','Together at LRS'),('community-7.jpg','Community initiatives'),('community-5.jpg','Welcoming students to LRS')]
    return '<div class="memory-gallery">'+''.join(f'<button class="gallery-item memory-item" type="button" data-poster="{media(photo)}" data-caption="{caption} · LRS original website archive">{img(photo,caption)}<span><small>0{i}</small>{caption}<b aria-hidden="true">↗</b></span></button>' for i,(photo,caption) in enumerate(items,1))+'</div>'

def partners():
    return f'<section class="section-small partners-section"><div class="wrap"><p class="eyebrow">Associations & collaborations</p><div class="partner-strip">'+''.join(img(f'partner-{n}.jpg',f'Partner logo from the original LRS website') for n in range(1,7))+f'</div><div class="sponsor-row"><p class="eyebrow">Our sponsors</p>'+''.join(img(name+'.png',title) for name,title in [('stylo','Stylo'),('tcr','Three Coffee Roasters'),('treet','Treet Hygiene')])+f'{link("https://lrs.lums.edu.pk/sponsors.html","Meet our sponsors")}</div></div></section>'

def home():
    return f'''<section class="cinema-hero" id="intro"><div class="hero-film"><video muted loop playsinline preload="metadata" poster="{media('hero-poster.jpg')}" aria-label="LRS campus archive film"><source src="{media('campus-film.mp4')}" type="video/mp4"></video><div class="hero-film-shade"></div></div><div class="hero-gridlines" aria-hidden="true"></div><div class="hero-spine"><span>01 / A shared intention</span><span>Lahore, Pakistan</span></div><div class="hero-editorial wrap"><p class="eyebrow hero-intro">Faith • Awareness • Integrity</p><h1><span>LUMS</span><span>Religious <em>Society.</em></span></h1><div class="hero-bottom"><p>{INTRO}</p><div class="hero-cta">{link('events','Explore our gatherings','btn gold-button')}{link('mosque/timings','Prayer timings','text-link')}</div></div></div><div class="hero-floor"><span>A vibrant sanctuary for the LUMS community</span><button type="button" data-film-toggle aria-pressed="false">Play background film ▷</button><a href="#gatherings">Scroll to discover ↓</a></div></section>
<div class="kinetic-strip" aria-hidden="true"><div class="kinetic-track">FAITH <i>✧</i> AWARENESS <i>✧</i> INTEGRITY <i>✧</i> COMMUNITY <i>✧</i> FAITH <i>✧</i> AWARENESS <i>✧</i> INTEGRITY <i>✧</i> COMMUNITY <i>✧</i></div></div>
{event_showcase()}{prayer_scene()}{community()}{verse()}
<section class="section pillars-section"><div class="wrap">{b.section_head('The three pillars of LRS','Rooted in faith.<br><em>Reaching further.</em>',description='Anchoring spiritual consciousness, rigorous inquiry, and community excellence across campus.')}{pillars()}</div></section>
<section class="festival-section section"><div class="wrap"><div class="festival-heading"><p class="eyebrow">LUMS Religious Festival</p><h2>More than an event.<br><em>A meeting of minds.</em></h2>{link('lrf','Explore LRF','btn gold-button')}</div><div class="festival-editions">{''.join(f'<a href="{b.url("lrf/"+edition)}" class="festival-edition"><span class="eyebrow">Edition archive</span><span class="edition-number">{edition}</span><span>Explore the festival <b aria-hidden="true">↗</b></span></a>' for edition in ['3.0','2.0','1.0'])}</div></div></section>
<section class="section tafakkur-home"><div class="wrap split"><div class="editorial-photo">{img('community-11.jpg','LRS academic gathering; archival contextual image')}<span>LRS learning & dialogue · archive</span></div><div class="prose"><p class="eyebrow">Tafakkur · Muslim Civilisational Think Tank</p><h2>Questions that<br><em>move us forward.</em></h2><p>Explore the society’s programme of masterclasses, collaborative policy labs, and civilisational inquiry through Economics, International Politics, Technology, and Education.</p>{link('tafakkur','Discover Tafakkur','btn')}</div></div></section>
<section class="solidarity-cinema"><div class="solidarity-backdrop">{img('community-7.jpg','LRS community initiative from the original site archive')}</div><div class="solidarity-shade"></div><div class="wrap solidarity-copy"><p class="eyebrow">Palestinian Cause</p><h2>Solidarity is<br><em>a shared responsibility.</em></h2><p>Standing together for justice, humanitarian relief, historical awareness, and collective community action.</p>{link('palestine','Explore solidarity initiatives','btn gold-button')}</div></section>
<section class="section"><div class="wrap">{b.section_head('Publications & learning','Read deeply.<br><em>Reflect sincerely.</em>',link('learn','Explore resources'))}<div class="grid">{b.resource('The Call','Society publications','Student voices, faith-based essays, poetry, and scholarly reflections.','publications','≋')}{b.resource('Quran circles','Learn together','Explore Surah Hadid and make space for regular reflection.','programmes/exploring-surah-hadid','۞')}{b.resource('LRS Newsletter','From the archive','Events, workshops, student initiatives, and life in the society.','publications','✧')}</div></div></section>
<section class="section memories-section"><div class="wrap">{b.section_head('Moments & memories','A community,<br><em>beautifully lived.</em>',link('gallery','Explore the gallery'))}<p class="muted">Capturing the memorable moments, communal bonds, and spiritual spirit across our sessions.</p>{gallery()}</div></section>
<section class="section philosophy-section"><div class="wrap split"><div><p class="eyebrow">Our philosophy</p><h2>Conviction through<br><em>sincere inquiry.</em></h2><p class="spaced philosophy-text">{PHILOSOPHY}</p><div class="spaced">{link('about','Learn about our full mission')}</div></div><div>{faq()}</div></div></section>{partners()}'''

def faq():
    items=[('What is the core mission of LRS?','Our society aims to foster spiritual growth, community engagement, and intellectual understanding of our shared beliefs through regular lectures, Arabic and Tajweed classes, charity drives, and academic seminars.'),('How can I become a member of the Religious Society?','Membership applications open at the start of the Fall semester during the annual LUMS Society Recruitment Drive. You can also reach out to us via email or Instagram for sub-committee inquiries.'),('What are the criteria to join LRS?','We look for dedication, sincerity, team spirit, and a passion for spreading positive awareness and community service across LUMS.'),('How inclusive is LRS towards students of all backgrounds?','LRS is warmly inclusive of all individuals regardless of background, providing a safe, welcoming, and open space for learning and dialogue.')]
    return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><div class="faq-answer"><p>{a}</p></div></details>' for q,a in items)+'</div>'

def about():
    return b.intro('About LRS','Faith. Awareness.<br><em>Integrity.</em>',INTRO)+f'<section class="section"><div class="wrap">{pillars()}</div></section><section class="section philosophy-section"><div class="wrap narrow prose"><p class="eyebrow">Our philosophy</p><h2>Spiritual conviction.<br><em>Open intellectual discourse.</em></h2><p>{PHILOSOPHY}</p>{link("contact","Contact the society","btn")}</div></section>'+partners()

def programme(p):
    return b.intro('Sisters’ Quran circle',p['title'],p['subtitle'])+f'<section class="section"><div class="wrap detail-grid"><article class="prose"><div class="editorial-photo">{img("lums-mosque.jpg","LUMS mosque exterior")}</div><p class="detail-description">{p["description"]}</p><h2>Begin where <em>you are.</em></h2><p>Whether you’ve attended the previous sessions or want to join for the first time, this circle is for you.</p>{link("https://quran.com/57","Read Surah Al-Hadid","btn")}</article><aside class="detail-sidebar"><dl><dt>Audience</dt><dd>Sisters</dd><dt>Schedule</dt><dd>{p["schedule"]}</dd><dt>Venue</dt><dd>{p["venue"]}</dd></dl><p class="fine">{p["timeNote"]}</p><div class="spaced">{link("mailto:faith@lums.edu.pk","Confirm the next session","btn")}</div></aside></div></section>'

def timings():
    return b.intro('LUMS Mosque Namaz Timings','Follow the light.<br><em>Make time for prayer.</em>','Current prayer and jama‘at schedule observed at the central LUMS Mosque.')+prayer_scene()+f'<section class="section"><div class="wrap"><div class="grid two"><article class="venue-card"><p class="eyebrow">Friday prayer</p><h3>Jumu‘ah</h3><p>Published jama‘at: 1:30 PM. Confirm the khutbah time and any special arrangements.</p>{link("https://lrs.lums.edu.pk/namazTimings.html","Official mosque timetable","btn")}</article><article class="venue-card"><p class="eyebrow">About the schedule</p><h3>Published times & live light</h3><p>Fajr, Asr, and Isha follow the original LRS half-month timetable. Zuhr is 1:30 PM. Maghrib is locally calculated sunset plus one minute, following the original site’s rule.</p><p class="fine">Published timetable snapshot: 30 October 2026. Always confirm special changes with the mosque. Sky movement is a visualisation of the solar day, not a prayer-start calculation.</p></article></div><div class="spaced">{link("mosque","Mosque facilities & community")}</div></div></section>'

def events_page():
    return b.intro('Events & archives','Gather around<br><em>something meaningful.</em>','Lectures, workshops, charity drives, spiritual assemblies, and the moments that bring our community together.')+event_showcase()+f'<section class="section" id="all-events"><div class="wrap">{b.section_head("Find your gathering","The community <em>agenda.</em>",link("events/agenda","Chronological view"))}{b.event_feed()}</div></section>'

def install(module):
    global b
    b=module
    for name in ['brand','layout','art','event_showcase','prayer_scene','pillars','programme_card','verse','gallery','home','faq','about','programme','timings','events_page']:
        setattr(b,name,globals()[name])
